import DataRanking from '@/components/data-ranking/data-ranking';
import CarClustererMap from '@/components/map/car-clusterer-map';
import KakaoMapScript from '@/components/map/kakao-map-script';
import MapModal from '@/components/map/map-modal';
import StatusContainer from '@/components/status-box/status-container';
import { CarService } from '@/services/car-service';
import {
  SingleCarLocationMessage,
  useMultipleCarWebSocket,
} from '@/services/websocket-service';
import { useCallback, useEffect, useState } from 'react';

export default function Home() {
  const [carStatusFilter, setCarStatusFilter] = useState<
    'total' | 'driving' | 'maintenance' | 'idle'
  >('total');

  const [isMapModalOpen, setIsMapModalOpen] = useState(false);
  const [drivingCarNumbers, setDrivingCarNumbers] = useState<string[]>([]);
  const [carLocationUpdates, setCarLocationUpdates] = useState<
    Map<string, SingleCarLocationMessage['data']>
  >(new Map());

  // 운행 중인 차량 목록을 가져와서 WebSocket 구독 설정
  useEffect(() => {
    const fetchDrivingCars = async () => {
      try {
        const drivingCars = await CarService.getCarsByStatus(['운행']);
        const carNumbers = drivingCars.map(car => car.carNumber);
        setDrivingCarNumbers(carNumbers);
        console.log('운행 중인 차량 목록:', carNumbers);
      } catch (error) {
        console.error('운행 중인 차량 목록 조회 실패:', error);
      }
    };

    fetchDrivingCars();
  }, []);

  // WebSocket으로 실시간 위치 업데이트 처리
  const handleCarLocationUpdate = useCallback(
    (carData: SingleCarLocationMessage['data']) => {
      setCarLocationUpdates(prev => {
        const newMap = new Map(prev);
        newMap.set(carData.carNumber, carData);
        return newMap;
      });
      console.log('실시간 위치 업데이트:', carData);
    },
    []
  );

  // 운행 중인 차량들 WebSocket 구독
  const multiCarWebSocket = useMultipleCarWebSocket(
    drivingCarNumbers,
    handleCarLocationUpdate,
    drivingCarNumbers.length > 0 // 운행 차량이 있을 때만 연결
  );

  // WebSocket 연결 성공 시 구독 시작
  useEffect(() => {
    if (multiCarWebSocket.isConnected && drivingCarNumbers.length > 0) {
      multiCarWebSocket.subscribeToMultipleCars();
    }

    // 컴포넌트 unmount 시 명시적으로 구독 해제 및 연결 종료
    return () => {
      if (multiCarWebSocket.isConnected) {
        multiCarWebSocket.unsubscribeFromMultipleCars();
      }
      // 페이지를 벗어날 때 WebSocket 연결 완전히 종료
      multiCarWebSocket.disconnect();

      if (process.env.NODE_ENV === 'development') {
        console.log('메인 페이지 unmount: 다중 차량 WebSocket 연결 종료');
      }
    };
  }, [multiCarWebSocket.isConnected, drivingCarNumbers]);
  return (
    <div className="flex flex-col">
      <DataRanking />
      <div className="flex flex-row gap-6 p-4 w-[98%] mx-auto">
        <>
          <StatusContainer
            carStatusFilter={carStatusFilter}
            setCarStatusFilter={setCarStatusFilter}
          />
        </>
        <div className="relative flex-1 max-h-[900px] rounded-2xl overflow-hidden border border-gray-200 shadow-lg transition-all duration-300 hover:shadow-xl">
          <KakaoMapScript />
          <CarClustererMap
            width="100%"
            height="100%"
            carStatusFilter={carStatusFilter}
            onOpenModal={() => setIsMapModalOpen(true)}
            isMapModalOpen={isMapModalOpen}
            realtimeCarData={carLocationUpdates}
          />
        </div>
      </div>
      <MapModal
        isOpen={isMapModalOpen}
        onClose={() => setIsMapModalOpen(false)}
      />
    </div>
  );
}
