import iconStyles from '@/components/icon-button/icon-button.module.css';
import CarLocationMap from '@/components/map/car-location-map';
import KakaoMapScript from '@/components/map/kakao-map-script';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { CarDetail, CarService } from '@/services/car-service';
import {
  SingleCarLocationMessage,
  useSingleCarWebSocket,
} from '@/services/websocket-service';
import { setDetailChangeStore } from '@/store/detail-change';
import { useDetailStore } from '@/store/detail-store';
import { ArrowLeft } from 'lucide-react';
import { useCallback, useEffect, useRef } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import styles from './detail.module.css';

const DetailPage = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const urlCarNumber = searchParams.get('carNumber');
  const intervalRef = useRef<NodeJS.Timeout | null>(null);
  const {
    carNumber,
    brand,
    model,
    status,
    carYear,
    sumDist,
    carType,
    setDetail,
    brandModel,
    lastLatitude,
    lastLongitude,
  } = useDetailStore();
  const detailChange = setDetailChangeStore(state => state.detailChange);
  const setDetailChange = setDetailChangeStore(state => state.setDetailChange);

  const goBack = useCallback(() => {
    window.history.back();
  }, []);

  // status가 undefined이거나 올바르지 않은 값일 때 기본값 처리
  const safeStatus = status ?? '대기';

  // 한국어 상태를 영어로 매핑
  const getEnglishStatus = (
    koreanStatus: string
  ): 'driving' | 'maintenance' | 'idle' => {
    switch (koreanStatus) {
      case '운행':
        return 'driving';
      case '수리':
        return 'maintenance';
      case '대기':
      default:
        return 'idle';
    }
  };

  // URL에서 carNumber가 있으면 API 호출해서 데이터 가져오기
  useEffect(() => {
    if (urlCarNumber) {
      const fetchCarDetail = async () => {
        try {
          const carDetail = await CarService.getCar(urlCarNumber);
          setDetail(carDetail);
        } catch (error) {
          console.error('차량 정보 로드 실패:', error);
          alert('차량 정보를 불러오는데 실패했습니다.');
          navigate('/search');
        }
      };
      fetchCarDetail();
    }
  }, [urlCarNumber, setDetail, navigate]);

  // WebSocket으로 실시간 위치 업데이트 처리 (운행 중일 때만)
  const handleCarLocationUpdate = useCallback(
    (carData: SingleCarLocationMessage['data']) => {
      // 받은 위치 데이터로 스토어 업데이트
      setDetail({
        carNumber: carData.carNumber,
        brand, // 기존 값 유지
        model, // 기존 값 유지
        brandModel, // 기존 값 유지
        status: carData.status,
        lastLatitude: carData.lastLatitude,
        lastLongitude: carData.lastLongitude,
        carYear, // 기존 값 유지
        sumDist, // 기존 값 유지
        carType, // 기존 값 유지
      });
      console.log(`차량 ${carData.carNumber} 실시간 위치 업데이트:`, carData);
    },
    [setDetail, brand, model, brandModel, carYear, sumDist, carType]
  );

  // 개별 차량 WebSocket 구독 (운행 중일 때만)
  const isCarDriving = status === '운행';
  const singleCarWebSocket = useSingleCarWebSocket(
    urlCarNumber || '',
    handleCarLocationUpdate,
    isCarDriving && !!urlCarNumber // 운행 중이고 차량번호가 있을 때만 연결
  );

  // WebSocket 연결 성공 시 구독 시작
  useEffect(() => {
    if (singleCarWebSocket.isConnected && isCarDriving && urlCarNumber) {
      singleCarWebSocket.subscribeToCarLocation();
    }

    // 컴포넌트 unmount 시 명시적으로 구독 해제 및 연결 종료
    return () => {
      if (singleCarWebSocket.isConnected && urlCarNumber) {
        singleCarWebSocket.unsubscribeFromCarLocation();
      }
      // 페이지를 벗어날 때 WebSocket 연결 완전히 종료
      singleCarWebSocket.disconnect();

      if (process.env.NODE_ENV === 'development') {
        console.log(
          `Detail 페이지 unmount: 차량 ${urlCarNumber} WebSocket 연결 종료`
        );
      }
    };
  }, [singleCarWebSocket.isConnected, isCarDriving, urlCarNumber]);

  // 운행 중이 아닌 경우 기존 polling 방식 유지 (백업용)
  useEffect(() => {
    if (!urlCarNumber || isCarDriving) return; // 운행 중이면 WebSocket 사용

    // 운행 중이 아닌 차량은 30초 간격으로 API 호출 (상태 변경 감지용)
    const intervalId = setInterval(async () => {
      try {
        const updatedCarDetail = await CarService.getCar(urlCarNumber);
        setDetail(updatedCarDetail);
      } catch (error) {
        console.error(`'${urlCarNumber}' 차량 정보 갱신 실패:`, error);
      }
    }, 30000); // 30초 (운행 중이 아니므로 긴 간격)

    return () => clearInterval(intervalId);
  }, [urlCarNumber, setDetail, isCarDriving]);

  const handleChange = (
    field: 'brandModel' | keyof CarDetail,
    value: string
  ) => {
    if (field === 'brandModel') {
      setDetail({
        carNumber,
        brand,
        brandModel: value,
        model,
        status,
        carYear,
        sumDist,
        carType,
      });
    } else {
      setDetail({
        carNumber,
        brand,
        brandModel,
        model,
        status,
        carYear,
        sumDist,
        carType,
        [field]: value,
      });
    }
  };

  const handleSave = async () => {
    try {
      // 브랜드와 모델을 분리하는 로직
      let finalBrand = brand;
      let finalModel = model;
      [finalBrand, finalModel] = brandModel.split(' ');
      console.log('분리된 브랜드,모델명');
      console.log(finalBrand, finalModel);

      const updateData: Partial<CarDetail> = {
        brand: finalBrand,
        model: finalModel,
        status,
        carYear,
        sumDist,
        carType,
      };

      await CarService.updateCar(carNumber, updateData);

      // 편집 모드 종료
      setDetailChange(false);

      // 성공 메시지 표시
      alert('차량 정보가 성공적으로 저장되었습니다.');

      // search 페이지로 라우트
      navigate('/search');
    } catch (error) {
      console.error('차량 정보 저장 실패:', error);
      alert('차량 정보 저장 중 오류가 발생했습니다.');
    }
  };

  return (
    <>
      <KakaoMapScript />
      <div className={styles.contentGrid}>
        {/* 상세 정보 */}
        <Card className={styles.detailCard}>
          <CardContent className={styles.cardContent}>
            <button onClick={goBack} className={iconStyles.goBack}>
              <ArrowLeft size={20} color="#535968" />
            </button>
            <div className={styles.title}>차량 정보</div>
            <div className={styles.formGrid}>
              <label className={styles.label}>차량 번호</label>

              <Input className={styles.input} value={carNumber} readOnly />
              <label className={styles.label}>차량 브랜드 이름</label>
              <Input
                className={styles.input}
                value={`${brandModel}`}
                readOnly={!detailChange}
                onChange={
                  detailChange
                    ? e => handleChange('brandModel', e.target.value)
                    : undefined
                }
              />
              <label className={styles.label}>상태</label>
              <Input
                className={styles.input}
                value={status}
                readOnly={!detailChange}
                onChange={
                  detailChange
                    ? e => handleChange('status', e.target.value)
                    : undefined
                }
              />
              <label className={styles.label}>차량 연식</label>
              <Input
                className={styles.input}
                value={carYear}
                readOnly={!detailChange}
                onChange={
                  detailChange
                    ? e => handleChange('carYear', e.target.value)
                    : undefined
                }
              />
              <label className={styles.label}>주행 거리 (km)</label>
              <Input
                className={styles.input}
                value={sumDist}
                readOnly={!detailChange}
                onChange={
                  detailChange
                    ? e => handleChange('sumDist', e.target.value)
                    : undefined
                }
              />
              <label className={styles.label}>차급</label>
              <Input
                className={styles.input}
                value={carType}
                readOnly={!detailChange}
                onChange={
                  detailChange
                    ? e => handleChange('carType', e.target.value)
                    : undefined
                }
              />
            </div>

            {detailChange && (
              <div className={styles.buttonContainer}>
                <Button className={styles.confirmButton} onClick={handleSave}>
                  확인
                </Button>
                <Button
                  className={styles.cancelButton}
                  onClick={() => {
                    setDetailChange(false);
                    navigate('/search');
                  }}
                >
                  취소
                </Button>
              </div>
            )}
          </CardContent>
        </Card>

        {/* 지도 */}
        <Card className={styles.mapCard}>
          <CardContent className={styles.mapContent}>
            <CarLocationMap
              width="100%"
              height="100%"
              carNumber={carNumber}
              lastLatitude={lastLatitude}
              lastLongitude={lastLongitude}
              status={getEnglishStatus(safeStatus)}
            />
          </CardContent>
        </Card>
      </div>
    </>
  );
};

export default DetailPage;
